"""Explain stack depot boot choices, parsing and early-init state transitions."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1889': ('보관함을 쓰려면 먼저 설치해야 해요. 사용 설명서만 가져왔다고 보관함까지 생기는 것은 아니에요.', '설정과 초기화 방법 세 가지, 저장 함수 사용 조건을 구별합니다.', '항상 초기화 설정·이른 요청·나중 init 세 길을 그려 준비된 저장소로 연결하세요.', ['stack depot은 같은 호출 경로 기록을 공유하는 저장소예요. 호출 경로는 어떤 함수들이 이어서 불렸는지 나타내는 기록이에요. 저장소를 쓰려면 기록을 찾을 표 등의 준비가 필요해요.', '공개 헤더는 초기화 방법 세 가지를 설명해요. 첫째는 CONFIG_STACKDEPOT_ALWAYS_INIT 설정이에요. 커널을 만들 때부터 저장소를 사용할 것을 알고 있으면 mm_init이라는 메모리 초기화 단계에서 준비하도록 선택할 수 있어요.', '둘째는 부팅 초기에 stack_depot_request_early_init을 호출해 요청하는 방법이에요. 이른 초기화 시점이 지나기 전에 요청해야 해요. 요청 표시와 실제 표를 만드는 작업은 다른 단계예요.', '셋째는 stack_depot_init을 호출하는 방법이에요. 부팅 뒤에도 가능한 경로이며 나중에 시작하는 모듈 등에 권장돼요. 모듈은 커널 기능을 별도로 추가하는 코드 단위예요. 구현은 mutex라는 잠금으로 동시 초기화 처리를 조절해요.', '헤더는 저장·조회·출력 함수를 쓰는 코드가 CONFIG_STACKDEPOT 활성과 초기화 수행을 보장해야 한다고 설명해요. 헤더를 include하는 것은 선언을 가져오는 일이지 저장소를 만드는 일은 아니에요. 초기화 실패나 비활성 정책도 함께 확인해야 해요.', '일부 초기화 API는 설정을 끈 경우 아무 작업 없는 대체 정의를 제공해요. 그래서 호출 형태를 유지할 수 있어도 실제 저장소가 생겼다는 뜻은 아니에요. 다른 저장 API까지 모든 설정에서 무조건 사용할 수 있다고 넓히지 마세요.'], [('저장 API를 사용하려면 호출하는 코드가 무엇을 먼저 보장해야 하나요?', ['헤더를 include하기만 하면 돼요', '기능 설정 활성과 필요한 초기화예요'], '정답은 두 번째예요. 선언을 읽을 수 있는 것과 저장소가 준비된 것은 달라요. 초기화의 실패·비활성 상태도 함께 처리해야 해요.'), ('부팅의 이른 초기화 단계가 지난 뒤 시작하는 모듈은 어떤 초기화 API를 사용할 수 있나요?', ['stack_depot_init이에요', '이미 지나간 early request만 반드시 사용해요'], '정답은 첫 번째예요. 공개 설명은 늦게 시작하는 모듈에 이 경로를 권장해요. 과거 단계에 대한 요청만 뒤늦게 바꾸는 것은 초기화 실행을 대신하지 않아요.')]), 'os1890': ('설정표의 글자 1이나 0을 읽어 켜짐·꺼짐 상태로 바꿔요. 읽을 수 없는 글자는 성공이라고 넘어가지 않고 오류를 돌려줘요.', '부팅 설정 문자열을 참·거짓으로 바꾸는 역할을 이해합니다.', '문자열 1→disabled true, 0→disabled false, bad→변환 오류의 세 줄을 적으세요.', ['stack_depot_disable은 이른 부팅 설정 이름이에요. 이름의 disable은 끄기라는 뜻이라 값이 참이면 저장소를 쓰지 않도록 하는 상태예요. disable_stack_depot 함수가 전달받은 문자열을 처리해요.', '본문은 kstrtobool(str, &stack_depot_disabled)의 결과를 그대로 반환해요. 문자열은 글자들이 이어진 값이고 bool은 참·거짓 값이에요. &는 결과를 써 넣을 변수의 주소를 전달한다는 뜻이에요.', '이 버전의 변환 도우미는 첫 글자 1 등을 참으로, 0 등을 거짓으로 해석해요. on과 off 형태도 구별해요. 정확한 허용 범위는 도우미의 실제 조건을 따라야 하며 임의의 영어 단어를 다 이해하는 기능은 아니에요.', '예를 들어 bad는 첫 글자 b가 허용 분기에 없어서 -EINVAL을 반환해요. EINVAL은 입력이 유효하지 않다는 오류 이름이고 앞의 마이너스는 오류 반환 표현이에요. 이 실패 경로는 결과 변수에 새 값을 쓰지 않아요.', '변환 성공은 0을 반환하고 stack_depot_disabled에 해석한 참·거짓을 써요. 문자열 1이 성공적으로 처리되면 disabled가 true가 되므로 저장 기능을 끄는 뜻이에요. 성공 숫자 0과 설정 내용 false를 같은 것으로 보지 마세요.', '이 설정은 저장소의 비활성 상태를 바꾸지 모든 객체의 데이터 바이트를 지우는 것이 아니에요. 부팅 인자를 전달하는 전체 경로와 이 작은 변환 함수도 역할을 나누어 읽어요. 실습에서는 설정을 실제 바꾸지 않고 세 입력의 결과를 계산해요.'], [('문자열 bad를 이 변환 도우미에 주면 반환 결과는 무엇인가요?', ['무조건 성공 0이에요', '유효하지 않은 입력을 뜻하는 -EINVAL이에요'], '정답은 두 번째예요. b는 이 도우미의 허용 분기에 없어요. 설정 이름을 안다고 아무 문자열이나 유효해지는 것은 아니에요.'), ('이 부팅 설정이 바꾸는 변수는 무엇인가요?', ['stack_depot_disabled예요', '모든 객체의 실제 데이터 값이에요'], '정답은 첫 번째예요. 함수가 그 변수 주소를 kstrtobool에 넘겨요. 저장 기능의 사용 여부와 저장된 메모리 내용 수정은 다른 일이에요.')]), 'os1891': ('접수가 끝난 뒤 신청서에 표시를 해도 지난 준비 작업이 자동으로 다시 열리지는 않아요. 요청 표시와 실제 실행을 구별해요.', '늦은 요청 경고와 요청 변수 대입의 순서를 이해합니다.', '시점 지남 확인→경고→실행이 계속되면 requested=true를 그리세요. 재초기화 호출은 없다고 적으세요.', ['stack_depot_request_early_init은 부팅 초기에 저장소 준비가 필요하다고 표시하는 함수예요. 이름의 request는 요청이라는 뜻이에요. 이 함수 자체가 해시 표를 할당하는 것은 아니에요.', '먼저 __stack_depot_early_init_passed를 WARN_ON으로 확인해요. passed는 이른 초기화 단계가 이미 지났다는 상태예요. 참이면 너무 늦은 요청이라고 경고해요.', '다음 문장은 __stack_depot_early_init_requested = true예요. 앞의 경고 뒤에 실행이 계속되면 이 대입도 이어져요. 이 함수의 경고는 if 조건으로 return을 선택하는 형태가 아니에요.', '일반 WARN_ON도 커널 설정에 따라 실행에 영향을 줄 수 있으므로 어떤 상황에서도 반드시 다음 줄이 실행된다고 단정하지 않아요. 핵심은 이 본문에 경고 때문에 대입을 건너뛰는 별도 반환문이 없다는 점이에요.', 'requested가 true가 되어도 이미 끝난 stack_depot_early_init을 다시 부르는 코드는 여기에 없어요. 재부팅을 요청하는 코드도 없어요. 상태를 쓰는 일과 그 상태를 읽는 초기화 단계를 실제 실행하는 것은 달라요.', '정상 사용에서는 헤더가 정한 시점 안에 요청해야 해요. 종이 모형으로 늦은 요청을 따라가는 것은 경고와 대입의 차이를 배우기 위한 것이며, 실제 부팅에서 시점 규칙을 어겨도 괜찮다는 뜻은 아니에요.'], [('너무 늦은 요청으로 경고했지만 실행이 계속된다면 requested 대입은 생략되나요?', ['네. WARN_ON 자체가 이 함수의 return이에요', '아니요. 뒤의 true 대입으로 이어져요'], '정답은 두 번째예요. 경고 다음 줄에 대입이 있고 별도 반환 분기는 없어요. 다만 경고 후 실행이 중단되는 설정까지 정상 진행으로 가정하면 안 돼요.'), ('늦게 requested를 true로 쓰면 지나간 초기화를 자동으로 다시 실행하나요?', ['아니요. 이 함수에는 그런 호출이 없어요', '네. 자동으로 재부팅하고 초기화해요'], '정답은 첫 번째예요. 함수는 요청 상태만 기록해요. 과거의 호출을 다시 실행하는 장치가 없으므로 부팅 호출 순서를 지켜야 해요.')]), 'os1892': ('준비 단계에 들어갔다는 표시와 실제 보관함을 만들었다는 표시는 같지 않아요. 중간 조건에 따라 준비를 건너뛸 수 있어요.', '이른 초기화의 진입 표시·생략·할당 실패를 구별합니다.', '최초 진입 표시→비활성이면 종료→요청 없으면 종료→표 할당→실패 시 비활성·오류로 흐름을 그리세요.', ['stack_depot_early_init은 부팅 초기에 기록 검색용 해시 표를 준비하는 함수예요. 해시 표는 요약값으로 후보 기록을 빠르게 찾는 자료구조예요. 원문은 mm_init에서 한 번 호출해야 한다고 설명해요.', '이미 passed가 참이면 if (WARN_ON(...)) return 0으로 돌아가요. 처음이라면 passed를 곧바로 true로 바꿔요. 이 표시는 함수에 처음 진입했다는 뜻이며 뒤의 모든 할당이 성공했다는 뜻은 아니에요.', 'stack_depot_disabled가 참이면 비활성 안내를 출력하고 0으로 돌아가요. 그 다음에는 KASAN이 켜졌고 표 크기 단계가 아직 정해지지 않았다면 최대 단계로 정해요. KASAN은 메모리 오류를 찾는 다른 검사 도구이며 많은 경로 기록이 생길 수 있어요.', '그 뒤 early init 요청이 없으면 0으로 돌아가요. 요청을 확인하기 전에 크기 정책을 정하는 이유는 나중 stack_depot_init도 이 값을 사용할 수 있기 때문이에요. 요청 없는 0 반환은 해시 표를 새로 만들었다는 보증이 아니에요.', '요청이 있으면 alloc_large_system_hash로 표를 할당해요. 결과가 없으면 실패 안내를 출력하고 stack_depot_disabled=true로 만든 뒤 -ENOMEM을 반환해요. ENOMEM은 필요한 메모리를 얻지 못했다는 오류 이름이에요.', '성공하면 표의 각 칸을 초기화하고 0을 반환해요. 따라서 0은 성공 완료, 비활성 생략, 요청 없음, 중복 호출 반환 등 여러 길에서 나와요. 반환값뿐 아니라 어떤 경로로 왔고 표가 실제 준비됐는지 함께 확인해야 해요.'], [('요청하지 않은 early_init이 0을 반환하면 해시 표가 반드시 만들어졌나요?', ['네. 0이면 언제나 표가 있어요', '아니요. 표 할당을 건너뛰는 경로가 있어요'], '정답은 두 번째예요. 요청 확인에서 일찍 돌아갈 수 있어요. passed=true도 진입 표시이지 표 할당 성공의 증거는 아니에요.'), ('이른 해시 표 할당이 실패하면 어떻게 처리하나요?', ['disabled를 true로 하고 -ENOMEM을 반환해요', '아무 주소나 성공 결과로 만들어 반환해요'], '정답은 첫 번째예요. 사용할 표가 없음을 비활성 상태와 오류로 알려요. 실패한 자원을 준비 완료로 취급하지 않아요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_468.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
